window.__CONTENT_EN__=window.__CONTENT_EN__||{};window.__CONTENT_EN__[86]={"8600":{"example:8600:exzh":"He works as a lecturer at a university.","example:8600:exzh2":"The lecturer talked about a new topic.","example:8600:exzh3":"The lecturer has built a good relationship with the students.","example:8600:exzh4":"My lecturer is very kind.","example:8600:exzh5":"The lecturer's classes are very interesting."},"8602":{"example:8602:exzh":"He has a criminal record.","example:8602:exzh2":"If you have a criminal record, finding a job is hard.","example:8602:exzh3":"This system does not take a criminal record into account.","example:8602:exzh4":"She hid her criminal record.","example:8602:exzh5":"A criminal record can't be helped, but life is still tough."},"8603":{"example:8603:exzh":"He is a very serious person.","example:8603:exzh2":"It's important to work seriously.","example:8603:exzh3":"She is a serious and reliable friend.","example:8603:exzh4":"It's a job that demands seriousness.","example:8603:exzh5":"You should approach it with a serious attitude."},"8604":{"example:8604:exzh":"That cloth is smooth.","example:8604:exzh2":"The skin is smooth.","example:8604:exzh3":"Smooth movement is needed.","example:8604:exzh4":"This cream sinks smoothly into the skin.","example:8604:exzh5":"A smooth way of speaking gives a good impression."},"8605":{"example:8605:exzh":"He used a cunning trick.","example:8605:exzh2":"Cunning behavior is not allowed.","example:8605:exzh3":"That person is a cunning merchant.","example:8605:exzh4":"The victory came from a cunning strategy.","example:8605:exzh5":"Sometimes a little cunning is necessary."},"8606":{"example:8606:exzh":"The human body has many organs.","example:8606:exzh2":"This organ plays an important role.","example:8606:exzh3":"Organ transplant surgery was performed.","example:8606:exzh4":"The heart is an important organ.","example:8606:exzh5":"It's important to keep your organs healthy."},"8607":{"example:8607:exzh":"Asters are flowers that bloom in autumn.","example:8607:exzh2":"I planted asters in the garden.","example:8607:exzh3":"The color of asters is very beautiful.","example:8607:exzh4":"There are many varieties of asters.","example:8607:exzh5":"Asters attract bees."},"8608":{"example:8608:exzh":"This item is worth a single mon.","example:8608:exzh2":"Not a single mon can be wasted.","example:8608:exzh3":"He doesn't have a single mon on him.","example:8608:exzh4":"I want to borrow even one mon.","example:8608:exzh5":"A difference of one mon makes a big impact."},"8609":{"example:8609:exzh":"He received disciplinary action.","example:8609:exzh2":"The reason for the disciplinary action is clear.","example:8609:exzh3":"A disciplinary system is needed.","example:8609:exzh4":"The rules on disciplinary action are being reviewed.","example:8609:exzh5":"You need to go through the disciplinary procedure."},"8610":{"example:8610:exzh":"That product is classified into a new category.","example:8610:exzh2":"We organized the information by dividing it into several categories.","example:8610:exzh3":"It's the most popular one in this category.","example:8610:exzh4":"There are different rules depending on the category.","example:8610:exzh5":"You can add a new category."},"8611":{"example:8611:exzh":"Fruit should be eaten after it ripens.","example:8611:exzh2":"This meat is well-aged and very tasty.","example:8611:exzh3":"Ripe tomatoes are sweet.","example:8611:exzh4":"You must not cook the rice until it is done.","example:8611:exzh5":"Ripe fruit is rich in nutrients."},"8612":{"example:8612:exzh":"The magpie is a Japanese bird.","example:8612:exzh2":"Magpies have beautiful feathers.","example:8612:exzh3":"Magpies are often seen in this area.","example:8612:exzh4":"The magpie is a symbol of prosperity.","example:8612:exzh5":"Magpies are smart birds."},"8613":{"example:8613:exzh":"This is off the record, so please don't write it up as an article.","example:8613:exzh2":"The minister spoke his true feelings off the record.","example:8613:exzh3":"His off-the-record remarks ended up in the newspaper.","example:8613:exzh4":"Please keep what follows off the record.","example:8613:exzh5":"The reporter who broke the off-the-record agreement lost credibility."},"8614":{"example:8614:exzh":"We need to check recent developments.","example:8614:exzh2":"Market trends are changing.","example:8614:exzh3":"This trend requires attention.","example:8614:exzh4":"It's important to grasp the trends.","example:8614:exzh5":"We'll take action based on the trends."},"8615":{"example:8615:exzh":"Both sides' opinions came into agreement.","example:8615:exzh2":"This agreement is important.","example:8615:exzh3":"We aim for agreement of opinions.","example:8615:exzh4":"Let's share the ideas we've come to agree on.","example:8615:exzh5":"If no agreement is reached, we'll discuss it again."},"8616":{"example:8616:exzh":"Playing in the light of day.","example:8616:exzh2":"People often go out during the daytime.","example:8616:exzh3":"I work during the daytime.","example:8616:exzh4":"The daylight hours are getting longer.","example:8616:exzh5":"The daytime sky is bright."},"8617":{"example:8617:exzh":"This prefecture has beautiful mountains.","example:8617:exzh2":"Aomori Prefecture is the northernmost prefecture in Honshu.","example:8617:exzh3":"I took part in the prefecture's festival.","example:8617:exzh4":"The people in the prefecture are friendly.","example:8617:exzh5":"This prefecture faces the ocean.","grammar:8617:ex:trans":"This prefecture has beautiful mountains.","grammar:8617:ex:structure":"県には＋美しい山があります","grammar:8617:ex:explain":"This is the existential pattern 「〜に〜がある」: the place particle 「に」 plus 「は」 becomes 「には」, which makes the place the topic, as in \"as for this prefecture, there are...\", with an implied contrast with other places. The real subject 「山」 takes 「が」 because it is the new information being introduced. 「美しい」 is an i-adjective and can modify a noun directly without changing form. Mountains are inanimate, so the sentence uses 「あります」 rather than 「います」.","grammar:8617:ex:words:0:zh":"this","grammar:8617:ex:words:0:pos":"pre-noun adjectival","grammar:8617:ex:words:1:zh":"prefecture","grammar:8617:ex:words:1:note":"けん","grammar:8617:ex:words:1:pos":"noun","grammar:8617:ex:words:2:zh":"at / on (location of existence + emphasis)","grammar:8617:ex:words:2:pos":"particle","grammar:8617:ex:words:3:zh":"beautiful","grammar:8617:ex:words:3:note":"うつくしい","grammar:8617:ex:words:3:pos":"adjective","grammar:8617:ex:words:4:zh":"mountain","grammar:8617:ex:words:4:note":"やま","grammar:8617:ex:words:4:pos":"noun","grammar:8617:ex:words:5:zh":"(nominative)","grammar:8617:ex:words:5:pos":"particle","grammar:8617:ex:words:6:zh":"there is / are","grammar:8617:ex:words:6:pos":"verb","grammar:8617:ex:points:0":"〜には〜がある: there is ~ in ~ (県に…山がある)","grammar:8617:ex:points:1":"i-adjective attributive modification: 美しい＋山 (beautiful mountains)","grammar:8617:ex2:trans":"Aomori Prefecture is the northernmost prefecture on Honshu.","grammar:8617:ex2:structure":"〜は、場所にある県です","grammar:8617:ex2:explain":"「青森県は」 introduces the place being described. 「本州の一番北」 indicates the northernmost point of Honshu, and 「にある」 means located there. Japanese places 「本州の一番北にある」 before 「県」, forming \"the prefecture located at the northernmost point of Honshu,\" and finishes the introduction with 「です」.","grammar:8617:ex2:words:0:zh":"Aomori Prefecture","grammar:8617:ex2:words:0:note":"あおもりけん","grammar:8617:ex2:words:0:pos":"noun","grammar:8617:ex2:words:1:zh":"(introduces the topic)","grammar:8617:ex2:words:1:pos":"particle","grammar:8617:ex2:words:2:zh":"Honshu","grammar:8617:ex2:words:2:note":"ほんしゅう","grammar:8617:ex2:words:2:pos":"noun","grammar:8617:ex2:words:3:zh":"(links nouns, showing the larger group something belongs to)","grammar:8617:ex2:words:3:pos":"particle","grammar:8617:ex2:words:4:zh":"the most","grammar:8617:ex2:words:4:note":"いちばん","grammar:8617:ex2:words:4:pos":"adverb","grammar:8617:ex2:words:5:zh":"north, northernmost","grammar:8617:ex2:words:5:note":"きた","grammar:8617:ex2:words:5:pos":"noun","grammar:8617:ex2:words:6:zh":"(the location where something exists)","grammar:8617:ex2:words:6:pos":"particle","grammar:8617:ex2:words:7:zh":"to be located, to exist","grammar:8617:ex2:words:7:pos":"verb","grammar:8617:ex2:words:8:zh":"prefecture","grammar:8617:ex2:words:8:note":"けん","grammar:8617:ex2:words:8:pos":"noun","grammar:8617:ex2:words:9:zh":"(states it politely)","grammar:8617:ex2:words:9:pos":"auxiliary verb","grammar:8617:ex2:points:0":"「場所にある」 means something is located somewhere, with the location marked by 「に」.","grammar:8617:ex2:points:1":"The whole phrase 「本州の一番北にある」 modifies 「県」.","grammar:8617:ex3:trans":"I took part in the prefecture's festival.","grammar:8617:ex3:structure":"県の祭りに＋参加しました","grammar:8617:ex3:words:0:zh":"I","grammar:8617:ex3:words:0:note":"わたし","grammar:8617:ex3:words:0:pos":"pronoun","grammar:8617:ex3:words:1:zh":"(topic)","grammar:8617:ex3:words:1:pos":"particle","grammar:8617:ex3:words:2:zh":"prefecture","grammar:8617:ex3:words:2:note":"けん","grammar:8617:ex3:words:2:pos":"noun","grammar:8617:ex3:words:3:zh":"'s","grammar:8617:ex3:words:3:pos":"particle","grammar:8617:ex3:words:4:zh":"festival","grammar:8617:ex3:words:4:note":"まつり","grammar:8617:ex3:words:4:pos":"noun","grammar:8617:ex3:words:5:zh":"(target of participation)","grammar:8617:ex3:words:5:pos":"particle","grammar:8617:ex3:words:6:zh":"join","grammar:8617:ex3:words:6:note":"さんかしました","grammar:8617:ex3:words:6:pos":"verb","grammar:8617:ex3:points:0":"〜に参加する: to take part in ~ (祭りに参加); に marks the target","grammar:8617:ex3:points:1":"の links nouns: 県の祭り (the prefecture's festival)","grammar:8617:ex4:trans":"The people of the prefecture are kind.","grammar:8617:ex4:structure":"県の人々は＋親切です","grammar:8617:ex4:words:0:zh":"prefecture","grammar:8617:ex4:words:0:note":"けん","grammar:8617:ex4:words:0:pos":"noun","grammar:8617:ex4:words:1:zh":"'s","grammar:8617:ex4:words:1:pos":"particle","grammar:8617:ex4:words:2:zh":"people","grammar:8617:ex4:words:2:note":"ひとびと","grammar:8617:ex4:words:2:pos":"noun","grammar:8617:ex4:words:3:zh":"(topic)","grammar:8617:ex4:words:3:pos":"particle","grammar:8617:ex4:words:4:zh":"kind, friendly","grammar:8617:ex4:words:4:note":"しんせつ","grammar:8617:ex4:words:4:pos":"na-adjective","grammar:8617:ex4:words:5:zh":"(assertion · polite)","grammar:8617:ex4:words:5:pos":"auxiliary verb","grammar:8617:ex4:points:0":"「親切だ」: polite assertion of a na-adjective (kind)","grammar:8617:ex4:points:1":"の links nouns: 県の人々 (the people of the prefecture)","grammar:8617:ex5:trans":"This prefecture faces the sea.","grammar:8617:ex5:structure":"海に＋面しています","grammar:8617:ex5:words:0:zh":"this","grammar:8617:ex5:words:0:pos":"pre-noun adjectival","grammar:8617:ex5:words:1:zh":"prefecture","grammar:8617:ex5:words:1:note":"けん","grammar:8617:ex5:words:1:pos":"noun","grammar:8617:ex5:words:2:zh":"(topic)","grammar:8617:ex5:words:2:pos":"particle","grammar:8617:ex5:words:3:zh":"sea","grammar:8617:ex5:words:3:note":"うみ","grammar:8617:ex5:words:3:pos":"noun","grammar:8617:ex5:words:4:zh":"(the thing faced)","grammar:8617:ex5:words:4:pos":"particle","grammar:8617:ex5:words:5:zh":"to face, to look out on","grammar:8617:ex5:words:5:note":"めんして (te-form)","grammar:8617:ex5:words:5:pos":"verb","grammar:8617:ex5:words:6:zh":"(ongoing state)","grammar:8617:ex5:words:6:pos":"auxiliary verb","grammar:8617:ex5:points:0":"〜に面する: to face ~ (海に面する = to face the sea); に marks the target","grammar:8617:ex5:points:1":"〜ている: here it describes an ongoing state (facing)"},"8618":{"example:8618:exzh":"Could you tell me his medical history?","example:8618:exzh2":"A medical history is necessary for treatment.","example:8618:exzh3":"Let's update the medical history regularly.","example:8618:exzh4":"It's important to check the medical history.","example:8618:exzh5":"I gave my medical history to the new doctor."},"8619":{"example:8619:exzh":"The plague of the Middle Ages claimed many lives.","example:8619:exzh2":"Today, treatments for the plague are well established.","example:8619:exzh3":"The plague is one of the infectious diseases.","example:8619:exzh4":"He is studying the history of the plague.","example:8619:exzh5":"People suffered greatly during the time the plague was spreading."},"8620":{"example:8620:exzh":"Japan has many different holidays.","example:8620:exzh2":"I spend holidays with my family.","example:8620:exzh3":"Schools are closed on holidays.","example:8620:exzh4":"I'm planning a trip for the holiday.","example:8620:exzh5":"This year's holidays are especially long."},"8621":{"example:8621:exzh":"May I borrow this book?","example:8621:exzh2":"I borrowed money from him.","example:8621:exzh3":"Be sure to return anything you borrow.","example:8621:exzh4":"I borrowed a friend's phone.","example:8621:exzh5":"Don't forget to say thank you when you borrow something."},"8622":{"example:8622:exzh":"I don't have any money on me.","example:8622:exzh2":"If you have money on you, you can go shopping.","example:8622:exzh3":"You should always keep important things with you.","example:8622:exzh4":"Please check the schedule you have with you.","example:8622:exzh5":"I'm reading a book I brought with me."},"8623":{"example:8623:exzh":"She was carrying a clutch bag.","example:8623:exzh2":"This clutch bag is very cute.","example:8623:exzh3":"Many people use clutch bags.","example:8623:exzh4":"I go out carrying a clutch bag.","example:8623:exzh5":"I'm looking for a stylish clutch bag."},"8624":{"example:8624:exzh":"Budapest has many beautiful buildings.","example:8624:exzh2":"Have you ever been to Budapest?","example:8624:exzh3":"The food in Budapest is really delicious.","example:8624:exzh4":"Budapest is a popular tourist destination.","example:8624:exzh5":"He spent a long time in Budapest."},"8625":{"example:8625:exzh":"Tairon is a soccer player.","example:8625:exzh2":"He and Tairon are friends.","example:8625:exzh3":"I really like Tairon's family.","example:8625:exzh4":"Tairon likes traveling.","example:8625:exzh5":"He watched a movie with Tairon."},"8627":{"example:8627:exzh":"The new app is a beta version.","example:8627:exzh2":"I'm taking part in the beta test.","example:8627:exzh3":"His game is still in beta.","example:8627:exzh4":"Please try the beta version.","example:8627:exzh5":"The beta version has bugs."},"8628":{"example:8628:exzh":"Hearing that story gave me the creeps.","example:8628:exzh2":"Her eyes sent a chill down my spine.","example:8628:exzh3":"I watched a movie that gave me the creeps.","example:8628:exzh4":"I heard a sound that made me shudder.","example:8628:exzh5":"Dark places can sometimes give you the creeps."},"8629":{"example:8629:exzh":"I've never seen a bug like this.","example:8629:exzh2":"Lots of bugs were found in the garden.","example:8629:exzh3":"He was insulted as a lowly otaku, no better than a bug.","example:8629:exzh4":"Even bugs are alive.","example:8629:exzh5":"This bug is dangerous."},"8630":{"example:8630:exzh":"I'm the second son.","example:8630:exzh2":"The second son likes soccer.","example:8630:exzh3":"The second son is a university student.","example:8630:exzh4":"His second son is very talented.","example:8630:exzh5":"The second son looks like his mother."},"8631":{"example:8631:exzh":"This tube is very old.","example:8631:exzh2":"There's treasure inside the tube.","example:8631:exzh3":"Use a tube to store documents.","example:8631:exzh4":"He's good at making sounds with a tube.","example:8631:exzh5":"This tube is made from eco-friendly materials."},"8632":{"example:8632:exzh":"He holds fascist ideas.","example:8632:exzh2":"Fascists restrict freedom.","example:8632:exzh3":"Fascism had a big influence on this era.","example:8632:exzh4":"Fascist rhetoric is dangerous.","example:8632:exzh5":"It's important to learn the history of fascism."},"8633":{"example:8633:exzh":"It stopped halfway.","example:8633:exzh2":"There will be a break halfway through.","example:8633:exzh3":"May I go home partway through?","example:8633:exzh4":"I'll report on the progress midway.","example:8633:exzh5":"Do you know what happened along the way?"},"8634":{"example:8634:exzh":"The cerebrum governs thinking.","example:8634:exzh2":"Consciousness is formed by the cerebrum.","example:8634:exzh3":"The cerebrum is the center of the nervous system.","example:8634:exzh4":"Research on the cerebrum is extremely important.","example:8634:exzh5":"When the cerebrum is tired, you can't concentrate."},"8635":{"example:8635:exzh":"He was half asleep.","example:8635:exzh2":"He had a sleepy, dazed look on his face.","example:8635:exzh3":"It's rare to talk while still half asleep.","example:8635:exzh4":"I was so groggy I don't remember anything.","example:8635:exzh5":"I went out for a walk while still half asleep."},"8636":{"example:8636:exzh":"Nitric acid is a strong acid.","example:8636:exzh2":"You need to be careful when handling nitric acid.","example:8636:exzh3":"Nitric acid is used in chemical reactions.","example:8636:exzh4":"Nitric acid is widely used in industry.","example:8636:exzh5":"Never drink nitric acid by mistake."},"8637":{"example:8637:exzh":"The temperature is zero degrees.","example:8637:exzh2":"His score is zero.","example:8637:exzh3":"The concept of zero is important.","example:8637:exzh4":"I got a zero on this test.","example:8637:exzh5":"Adding zero doesn't change anything."},"8638":{"example:8638:exzh":"Please speak on his behalf.","example:8638:exzh2":"I'll take over right away.","example:8638:exzh3":"I'll send the materials by email on his behalf.","example:8638:exzh4":"He can't take over.","example:8638:exzh5":"Someone will take over, I expect.","grammar:8638:ex:trans":"Please switch with him and talk.","grammar:8638:ex:structure":"彼と代わって話してください","grammar:8638:ex:explain":"「代わる」 is an intransitive verb meaning that someone else takes over or stands in; the counterpart is marked with 「と」 or 「に」, so 「彼と代わる」 means to switch places with him. Here the te-form 「代わって」 links to the next action 「話してください」, showing that you switch first and then speak. Watch out for four homophones: 「代わる」 is to substitute, 「変わる」 is to change, 「替わる」 is to replace, and 「換わる」 is to swap — it is easy to pick the wrong kanji when writing.","grammar:8638:ex:words:0:zh":"he","grammar:8638:ex:words:0:note":"かれ","grammar:8638:ex:words:0:pos":"pronoun","grammar:8638:ex:words:1:zh":"(object)","grammar:8638:ex:words:1:pos":"particle","grammar:8638:ex:words:2:zh":"in place of","grammar:8638:ex:words:2:note":"かわって","grammar:8638:ex:words:2:pos":"verb","grammar:8638:ex:words:3:zh":"speaking","grammar:8638:ex:words:3:note":"はなして","grammar:8638:ex:words:3:pos":"verb","grammar:8638:ex:words:4:zh":"please","grammar:8638:ex:words:4:pos":"auxiliary verb","grammar:8638:ex:points:0":"❗代わる（かわる）: to substitute, to stand in (someone else takes over; intransitive verb) + と／に; four homophones: 「代わる」= substitute, 「変わる」= change, 「替わる」= replace, 「換わる」= swap.","grammar:8638:ex:points:1":"代わる: to substitute (vs 変わる to change / 替わる to replace / 換わる to swap).","grammar:8638:ex2:trans":"I'll take over right away.","grammar:8638:ex2:structure":"すぐに私が代わります","grammar:8638:ex2:words:0:zh":"soon","grammar:8638:ex2:words:0:pos":"adverb","grammar:8638:ex2:words:1:zh":"I","grammar:8638:ex2:words:1:note":"わたし","grammar:8638:ex2:words:1:pos":"pronoun","grammar:8638:ex2:words:2:zh":"(nominative)","grammar:8638:ex2:words:2:pos":"particle","grammar:8638:ex2:words:3:zh":"to take over","grammar:8638:ex2:words:3:note":"かわります","grammar:8638:ex2:words:3:pos":"verb","grammar:8638:ex2:points:0":"❗私が代わる: I'll take over.","grammar:8638:ex2:points:1":"私が代わる: I'll take over.","grammar:8638:ex3:trans":"I'll send the documents by email on his behalf.","grammar:8638:ex3:structure":"人に代わって (on someone's behalf) + means で + 〜を送ります","grammar:8638:ex3:explain":"「私が」 marks the person who actually sends the documents, and in the right context it can also emphasize that I am the one doing it. 「彼に代わって」 means carrying out this task in his place, with the person being replaced marked by 「に」. 「メールで」 explains the method of sending, 「資料を」 marks what is being sent, and 「送ります」 can mean the documents will be sent next, depending on the situation.","grammar:8638:ex3:words:0:zh":"I","grammar:8638:ex3:words:0:note":"わたし","grammar:8638:ex3:words:0:pos":"pronoun","grammar:8638:ex3:words:1:zh":"(nominative)","grammar:8638:ex3:words:1:pos":"particle","grammar:8638:ex3:words:2:zh":"he","grammar:8638:ex3:words:2:note":"かれ","grammar:8638:ex3:words:2:pos":"pronoun","grammar:8638:ex3:words:3:zh":"(the person being replaced)","grammar:8638:ex3:words:3:pos":"particle","grammar:8638:ex3:words:4:zh":"instead of","grammar:8638:ex3:words:4:note":"かわっ","grammar:8638:ex3:words:4:pos":"verb","grammar:8638:ex3:words:5:zh":"(connects actions, expressing a relation of doing something in someone's place)","grammar:8638:ex3:words:5:pos":"particle","grammar:8638:ex3:words:6:zh":"email","grammar:8638:ex3:words:6:pos":"noun","grammar:8638:ex3:words:7:zh":"(tool, means)","grammar:8638:ex3:words:7:pos":"particle","grammar:8638:ex3:words:8:zh":"materials","grammar:8638:ex3:words:8:note":"しりょう","grammar:8638:ex3:words:8:pos":"noun","grammar:8638:ex3:words:9:zh":"(object)","grammar:8638:ex3:words:9:pos":"particle","grammar:8638:ex3:words:10:zh":"to send, to transmit","grammar:8638:ex3:words:10:note":"おくり","grammar:8638:ex3:words:10:pos":"verb","grammar:8638:ex3:words:11:zh":"(polite ending)","grammar:8638:ex3:words:11:pos":"auxiliary verb","grammar:8638:ex3:points:0":"「人に代わって」 means doing an action in place of someone else.","grammar:8638:ex3:points:1":"The 「で」 in 「メールで」 marks the means of sending the documents.","grammar:8638:ex4:trans":"He can't take over.","grammar:8638:ex4:structure":"彼が代わることができません","grammar:8638:ex4:words:0:zh":"he","grammar:8638:ex4:words:0:note":"かれ","grammar:8638:ex4:words:0:pos":"pronoun","grammar:8638:ex4:words:1:zh":"(nominative)","grammar:8638:ex4:words:1:pos":"particle","grammar:8638:ex4:words:2:zh":"to take over","grammar:8638:ex4:words:2:note":"かわる","grammar:8638:ex4:words:2:pos":"verb","grammar:8638:ex4:words:3:zh":"(nominalizer)","grammar:8638:ex4:words:3:pos":"noun","grammar:8638:ex4:words:4:zh":"(nominative)","grammar:8638:ex4:words:4:pos":"particle","grammar:8638:ex4:words:5:zh":"can't","grammar:8638:ex4:words:5:pos":"verb","grammar:8638:ex4:points:0":"❗代わることができない: no one can take over.","grammar:8638:ex4:points:1":"代わることができない: no one can take over.","grammar:8638:ex5:trans":"Someone will take over, I suppose.","grammar:8638:ex5:structure":"誰かが代わってくれるでしょう","grammar:8638:ex5:words:0:zh":"someone","grammar:8638:ex5:words:0:note":"だれか","grammar:8638:ex5:words:0:pos":"pronoun","grammar:8638:ex5:words:1:zh":"(nominative)","grammar:8638:ex5:words:1:pos":"particle","grammar:8638:ex5:words:2:zh":"to take over","grammar:8638:ex5:words:2:note":"かわって","grammar:8638:ex5:words:2:pos":"verb","grammar:8638:ex5:words:3:zh":"(to me)","grammar:8638:ex5:words:3:pos":"auxiliary verb","grammar:8638:ex5:words:4:zh":"probably","grammar:8638:ex5:words:4:pos":"auxiliary verb","grammar:8638:ex5:points:0":"❗代わってくれる: someone takes over for you.","grammar:8638:ex5:points:1":"代わってくれる: someone takes over for you."},"8639":{"example:8639:exzh":"He has a severe allergy.","example:8639:exzh2":"They're suffering from a severe addiction.","example:8639:exzh3":"This illness may become more severe.","example:8639:exzh4":"People with severe disabilities need support.","example:8639:exzh5":"If severe symptoms appear, please see a doctor."},"8641":{"example:8641:exzh":"The ship spread its sails and moved forward.","example:8641:exzh2":"When you raise the sail, it catches the wind.","example:8641:exzh3":"A sailing ship uses the wind to travel.","example:8641:exzh4":"He is good at handling sails.","example:8641:exzh5":"But if the sail tears, it's a real problem."},"8642":{"example:8642:exzh":"Balance in your diet is important.","example:8642:exzh2":"Let's try to eat a balanced diet.","example:8642:exzh3":"Losing that balance is bad for your body.","example:8642:exzh4":"Mental balance matters too.","example:8642:exzh5":"Let's exercise to keep our balance."},"8643":{"example:8643:exzh":"He calls himself a writer.","example:8643:exzh2":"Before trusting a self-proclaimed expert, you should check the facts.","example:8643:exzh3":"A man who called himself the company president came to visit.","example:8643:exzh4":"Calling yourself something is part of self-expression.","example:8643:exzh5":"You're judged by ability, not by what you call yourself."},"8644":{"example:8644:exzh":"The design of this house has a very old-fashioned feel.","example:8644:exzh2":"He likes old-fashioned music.","example:8644:exzh3":"Old-fashioned furniture decorates the room.","example:8644:exzh4":"Her clothes are in an old-fashioned style.","example:8644:exzh5":"There's a café with an old-fashioned atmosphere."},"8645":{"example:8645:exzh":"When summer comes, I walk barefoot.","example:8645:exzh2":"I like running barefoot on the beach.","example:8645:exzh3":"I'm always barefoot at home.","example:8645:exzh4":"I took a walk barefoot in the park.","example:8645:exzh5":"Being barefoot feels great."},"8646":{"example:8646:exzh":"I returned the book at the library.","example:8646:exzh2":"Please meet the return deadline.","example:8646:exzh3":"I'm planning to return the movie to my friend.","example:8646:exzh4":"Before you leave, don't forget to complete the return procedure.","example:8646:exzh5":"The return box is over there."},"8647":{"example:8647:exzh":"She is a very kind stepmother.","example:8647:exzh2":"My stepmother is a good cook.","example:8647:exzh3":"My relationship with my stepmother is good.","example:8647:exzh4":"In the movie, the stepmother is a main character.","example:8647:exzh5":"I'm going to celebrate my stepmother's birthday."},"8648":{"example:8648:exzh":"Please indicate on the application form whether you have a spouse.","example:8648:exzh2":"He was blessed with a good spouse.","example:8648:exzh3":"There are conditions for receiving the spousal deduction.","example:8648:exzh4":"Some procedures require your spouse's consent.","example:8648:exzh5":"You may bring your spouse to the party."},"8649":{"example:8649:exzh":"He works as a worker at a construction site.","example:8649:exzh2":"Protecting workers' rights is important.","example:8649:exzh3":"Workers gathered and held a demonstration.","example:8649:exzh4":"Many workers work at this company.","example:8649:exzh5":"The workers are demanding better working conditions."},"8650":{"example:8650:exzh":"He has a lot of bundles of cash.","example:8650:exzh2":"This bundle of cash is very heavy.","example:8650:exzh3":"I withdrew a bundle of cash from the bank.","example:8650:exzh4":"Counting bundles of cash is fun.","example:8650:exzh5":"She put the bundle of cash in her bag."},"8651":{"example:8651:exzh":"The lights will be lit at Christmas.","example:8651:exzh2":"This light bulb isn't on.","example:8651:exzh3":"I turned on the street lights.","example:8651:exzh4":"Many lights are lit at the festival.","example:8651:exzh5":"He lit the candle."},"8653":{"example:8653:exzh":"He is troubled by insomnia.","example:8653:exzh2":"The insomnia continues.","example:8653:exzh3":"Insomnia is bad for your health.","example:8653:exzh4":"She went to the doctor because of insomnia.","example:8653:exzh5":"I'm worried about my insomnia."},"8655":{"example:8655:exzh":"The ecosystem in this region is very diverse.","example:8655:exzh2":"Protecting the ecological environment is important.","example:8655:exzh3":"I like learning about ecology.","example:8655:exzh4":"Ecologists are working to protect this species.","example:8655:exzh5":"Changes in the ecosystem affect the whole planet."},"8656":{"example:8656:exzh":"We're taking music requests.","example:8656:exzh2":"He made a special request.","example:8656:exzh3":"It's important to respond to requests.","example:8656:exzh4":"This request will be handled right away.","example:8656:exzh5":"If you have a request, please let me know."},"8658":{"example:8658:exzh":"A new idea is needed.","example:8658:exzh2":"His idea was excellent.","example:8658:exzh3":"The idea was presented at the meeting.","example:8658:exzh4":"She is good at coming up with ideas.","example:8658:exzh5":"This idea is feasible."},"8659":{"example:8659:exzh":"I have absolutely no idea what he's doing.","example:8659:exzh2":"This problem can't possibly be solved.","example:8659:exzh3":"Can you really bring yourself to believe that?","example:8659:exzh4":"Please tell me what on earth happened.","example:8659:exzh5":"She just couldn't accept it."},"8660":{"example:8660:exzh":"He blocked the way forward.","example:8660:exzh2":"That action will hinder the plan.","example:8660:exzh3":"Bad weather is getting in the way of the trip.","example:8660:exzh4":"No one could stop him.","example:8660:exzh5":"He worked hard to stop the problem."},"8662":{"example:8662:exzh":"He feels distrust.","example:8662:exzh2":"Distrust can ruin a relationship.","example:8662:exzh3":"Distrust of society is growing.","example:8662:exzh4":"She feels distrust toward other people.","example:8662:exzh5":"There are various reasons why distrust arises."},"8666":{"example:8666:exzh":"She is a celebrity's personal assistant.","example:8666:exzh2":"A personal assistant's job is tough.","example:8666:exzh3":"His assistant is always by his side.","example:8666:exzh4":"Working as a personal assistant is fun.","example:8666:exzh5":"I have experience working as a personal assistant."},"8667":{"example:8667:exzh":"He is a porter who carries luggage.","example:8667:exzh2":"There was a porter at the airport.","example:8667:exzh3":"Being a porter is hard work.","example:8667:exzh4":"At the hotel, the porter welcomed us warmly.","example:8667:exzh5":"You can use the porter service."},"8668":{"example:8668:exzh":"He put wax on the shoes.","example:8668:exzh2":"Car wax is needed.","example:8668:exzh3":"When you apply wax to furniture, it gets a shine.","example:8668:exzh4":"I used wax to style my hair.","example:8668:exzh5":"Wax can be used for many purposes."},"8669":{"example:8669:exzh":"She wanted to forget everything.","example:8669:exzh2":"It's hard to forget the bitter memories of the past.","example:8669:exzh3":"He quickly forgot all about it.","example:8669:exzh4":"I can't forget everything.","example:8669:exzh5":"You mustn't forget the happy memories."},"8670":{"example:8670:exzh":"I handed out the materials.","example:8670:exzh2":"The event flyers are being handed out.","example:8670:exzh3":"Please take a look at the pamphlets that were handed out.","example:8670:exzh4":"Has the distribution schedule been decided yet?","example:8670:exzh5":"The information that was handed out was accurate."},"8671":{"example:8671:exzh":"I ate a sandwich for breakfast.","example:8671:exzh2":"Sandwiches are perfect for lunch.","example:8671:exzh3":"He likes sandwiches.","example:8671:exzh4":"This sandwich is delicious.","example:8671:exzh5":"I ordered a sandwich and juice.","grammar:8671:ex:trans":"I had a sandwich for breakfast.","grammar:8671:ex:structure":"朝食に、サンドウィッチを＋食べました. 「〜に」 marks a point in time.","grammar:8671:ex:explain":"The 「に」 here isn't a simple point in time; it means on that occasion, as that meal, so 「朝食に」 means as breakfast, eaten at breakfast time. A parallel example is 「おやつにケーキを食べる」. Note that if you say 「朝ご飯を食べました」, the meal itself becomes the object, so the particle changes accordingly. 「食べました」 is the polite past of an ichidan verb.","grammar:8671:ex:words:0:zh":"breakfast","grammar:8671:ex:words:0:note":"ちょうしょく","grammar:8671:ex:words:0:pos":"noun","grammar:8671:ex:words:1:zh":"(point in time)","grammar:8671:ex:words:1:pos":"particle","grammar:8671:ex:words:2:zh":"sandwich","grammar:8671:ex:words:2:note":"loanword","grammar:8671:ex:words:2:pos":"noun","grammar:8671:ex:words:3:zh":"(object marker)","grammar:8671:ex:words:3:pos":"particle","grammar:8671:ex:words:4:zh":"ate","grammar:8671:ex:words:4:note":"たべました","grammar:8671:ex:words:4:pos":"verb","grammar:8671:ex:points:0":"朝食に: at breakfast","grammar:8671:ex:points:1":"サンドウィッチ: sandwich","grammar:8671:ex2:trans":"A sandwich is perfect for lunch.","grammar:8671:ex2:structure":"サンドウィッチは、お昼に＋最適です. 「〜に最適」 means perfect for …","grammar:8671:ex2:words:0:zh":"sandwich","grammar:8671:ex2:words:0:note":"loanword","grammar:8671:ex2:words:0:pos":"noun","grammar:8671:ex2:words:1:zh":"(topic marker)","grammar:8671:ex2:words:1:pos":"particle","grammar:8671:ex2:words:2:zh":"lunch","grammar:8671:ex2:words:2:note":"おひる","grammar:8671:ex2:words:2:pos":"noun","grammar:8671:ex2:words:3:zh":"(object)","grammar:8671:ex2:words:3:pos":"particle","grammar:8671:ex2:words:4:zh":"best suited for","grammar:8671:ex2:words:4:note":"さいてき","grammar:8671:ex2:words:4:pos":"na-adjective","grammar:8671:ex2:words:5:zh":"(polite form)","grammar:8671:ex2:words:5:pos":"copula","grammar:8671:ex2:points:0":"〜に最適: perfect for …","grammar:8671:ex2:points:1":"お昼: lunch, midday","grammar:8671:ex3:trans":"He likes sandwiches.","grammar:8671:ex3:structure":"〜は＋サンドウィッチが＋好きです.","grammar:8671:ex3:words:0:zh":"he","grammar:8671:ex3:words:0:note":"かれ","grammar:8671:ex3:words:0:pos":"pronoun","grammar:8671:ex3:words:1:zh":"(topic marker)","grammar:8671:ex3:words:1:pos":"particle","grammar:8671:ex3:words:2:zh":"sandwich","grammar:8671:ex3:words:2:note":"loanword","grammar:8671:ex3:words:2:pos":"noun","grammar:8671:ex3:words:3:zh":"(object marker)","grammar:8671:ex3:words:3:pos":"particle","grammar:8671:ex3:words:4:zh":"to like","grammar:8671:ex3:words:4:note":"すき","grammar:8671:ex3:words:4:pos":"na-adjective","grammar:8671:ex3:words:5:zh":"(polite form)","grammar:8671:ex3:words:5:pos":"copula","grammar:8671:ex3:points:0":"〜が好きです: like …","grammar:8671:ex3:points:1":"サンドウィッチ: sandwich","grammar:8671:ex4:trans":"This sandwich is delicious.","grammar:8671:ex4:structure":"この＋noun＋は＋i-adjective＋です。","grammar:8671:ex4:words:0:zh":"this","grammar:8671:ex4:words:0:pos":"pre-noun adjectival","grammar:8671:ex4:words:1:zh":"sandwich","grammar:8671:ex4:words:1:note":"loanword","grammar:8671:ex4:words:1:pos":"noun","grammar:8671:ex4:words:2:zh":"(topic marker)","grammar:8671:ex4:words:2:pos":"particle","grammar:8671:ex4:words:3:zh":"tasty","grammar:8671:ex4:words:3:pos":"adjective","grammar:8671:ex4:words:4:zh":"(polite form)","grammar:8671:ex4:words:4:pos":"copula","grammar:8671:ex4:points:0":"おいしい: tasty","grammar:8671:ex4:points:1":"このサンドウィッチ: this sandwich","grammar:8671:ex5:trans":"I ordered a sandwich and juice.","grammar:8671:ex5:structure":"〔サンドウィッチとジュース〕＋を＋注文しました. 「A と B」 means A and B.","grammar:8671:ex5:words:0:zh":"sandwich","grammar:8671:ex5:words:0:note":"loanword","grammar:8671:ex5:words:0:pos":"noun","grammar:8671:ex5:words:1:zh":"with","grammar:8671:ex5:words:1:pos":"particle","grammar:8671:ex5:words:2:zh":"juice","grammar:8671:ex5:words:2:note":"loanword","grammar:8671:ex5:words:2:pos":"noun","grammar:8671:ex5:words:3:zh":"(object marker)","grammar:8671:ex5:words:3:pos":"particle","grammar:8671:ex5:words:4:zh":"ordered","grammar:8671:ex5:words:4:note":"ちゅうもんしました","grammar:8671:ex5:words:4:pos":"verb","grammar:8671:ex5:points:0":"〜と〜: … and … (listing)","grammar:8671:ex5:points:1":"注文する: to order"},"8673":{"example:8673:exzh":"We'll get into formation and move forward.","example:8673:exzh2":"We need to change formation while marching.","example:8673:exzh3":"Be careful not to let the formation fall apart.","example:8673:exzh4":"The formation during the drill was beautiful.","example:8673:exzh5":"We'll check the formation and then set off."},"8674":{"example:8674:exzh":"Please keep this position.","example:8674:exzh2":"It's hard to keep your weight steady.","example:8674:exzh3":"He is keeping that state.","example:8674:exzh4":"Please don't move while you're holding it.","example:8674:exzh5":"It's important to stick to the plan."},"8677":{"example:8677:exzh":"Beef is very nutritious.","example:8677:exzh2":"I love steak, especially beef.","example:8677:exzh3":"There are many dishes made with beef.","example:8677:exzh4":"This beef is tender and delicious.","example:8677:exzh5":"Beef dishes are famous in Japan.","grammar:8677:ex:trans":"Beef is very rich in nutrients.","grammar:8677:ex:structure":"牛肉は、とても＋栄養が＋豊富です. 「〜は〜が豊富」 means … is rich in (a certain aspect).","grammar:8677:ex:explain":"This is the classic 「〜は〜が」 double-subject sentence: 「は」 sets the broad topic 「牛肉」, and 「が」 picks out the aspect being described, 「栄養」, so the whole sentence means as for beef, its nutrition is rich. This structure is extremely common for describing attributes — the famous 「象は鼻が長い」 works the same way. 「豊富だ」 is a na-adjective: it takes 「です」 at the end to become polite, and uses 「な」 only when modifying a noun.","grammar:8677:ex:words:0:zh":"beef","grammar:8677:ex:words:0:note":"ぎゅうにく","grammar:8677:ex:words:0:pos":"noun","grammar:8677:ex:words:1:zh":"(topic marker)","grammar:8677:ex:words:1:pos":"particle","grammar:8677:ex:words:2:zh":"extremely","grammar:8677:ex:words:2:pos":"adverb","grammar:8677:ex:words:3:zh":"nutrition","grammar:8677:ex:words:3:note":"えいよう","grammar:8677:ex:words:3:pos":"noun","grammar:8677:ex:words:4:zh":"(nominative)","grammar:8677:ex:words:4:pos":"particle","grammar:8677:ex:words:5:zh":"abundant","grammar:8677:ex:words:5:note":"ほうふ","grammar:8677:ex:words:5:pos":"na-adjective","grammar:8677:ex:words:6:zh":"(polite form)","grammar:8677:ex:words:6:pos":"copula","grammar:8677:ex:points:0":"牛肉 (ぎゅうにく): beef","grammar:8677:ex:points:1":"栄養が豊富: rich in nutrients","grammar:8677:ex2:trans":"I love steak, especially beef.","grammar:8677:ex2:structure":"〜は＋ステーキが＋大好きです. 特に＋牛肉が＋好みです. 「特に」 means especially, and 「〜が好み」 means to have a preference for …","grammar:8677:ex2:words:0:zh":"I","grammar:8677:ex2:words:0:note":"わたし","grammar:8677:ex2:words:0:pos":"pronoun","grammar:8677:ex2:words:1:zh":"(topic marker)","grammar:8677:ex2:words:1:pos":"particle","grammar:8677:ex2:words:2:zh":"steak","grammar:8677:ex2:words:2:note":"loanword","grammar:8677:ex2:words:2:pos":"noun","grammar:8677:ex2:words:3:zh":"(object marker)","grammar:8677:ex2:words:3:pos":"particle","grammar:8677:ex2:words:4:zh":"Love","grammar:8677:ex2:words:4:note":"だいすき","grammar:8677:ex2:words:4:pos":"na-adjective","grammar:8677:ex2:words:5:zh":"(polite form)","grammar:8677:ex2:words:5:pos":"copula","grammar:8677:ex2:words:6:zh":"especially","grammar:8677:ex2:words:6:note":"とくに","grammar:8677:ex2:words:6:pos":"adverb","grammar:8677:ex2:words:7:zh":"beef","grammar:8677:ex2:words:7:note":"ぎゅうにく","grammar:8677:ex2:words:7:pos":"noun","grammar:8677:ex2:words:8:zh":"(object marker)","grammar:8677:ex2:words:8:pos":"particle","grammar:8677:ex2:words:9:zh":"preference","grammar:8677:ex2:words:9:note":"このみ","grammar:8677:ex2:words:9:pos":"noun","grammar:8677:ex2:words:10:zh":"(polite form)","grammar:8677:ex2:words:10:pos":"copula","grammar:8677:ex2:points:0":"特に: especially, in particular","grammar:8677:ex2:points:1":"〜が好み: to prefer … (好み = preference)","grammar:8677:ex3:trans":"There are many dishes made with beef.","grammar:8677:ex3:structure":"〔牛肉を使った〕＋料理＋は＋たくさん＋あります. 「牛肉を使った」 modifies 「料理」.","grammar:8677:ex3:words:0:zh":"beef","grammar:8677:ex3:words:0:note":"ぎゅうにく","grammar:8677:ex3:words:0:pos":"noun","grammar:8677:ex3:words:1:zh":"(object marker)","grammar:8677:ex3:words:1:pos":"particle","grammar:8677:ex3:words:2:zh":"using","grammar:8677:ex3:words:2:note":"ta-form modification","grammar:8677:ex3:words:2:pos":"verb","grammar:8677:ex3:words:3:zh":"dish / cuisine","grammar:8677:ex3:words:3:note":"りょうり","grammar:8677:ex3:words:3:pos":"noun","grammar:8677:ex3:words:4:zh":"(topic marker)","grammar:8677:ex3:words:4:pos":"particle","grammar:8677:ex3:words:5:zh":"a lot","grammar:8677:ex3:words:5:pos":"adverb","grammar:8677:ex3:words:6:zh":"there is / are","grammar:8677:ex3:words:6:note":"exists / there is","grammar:8677:ex3:words:6:pos":"verb","grammar:8677:ex3:points:0":"Verb ta-form modifying a noun: 使った料理 (a dish made with…)","grammar:8677:ex3:points:1":"牛肉を使う: to use beef","grammar:8677:ex4:trans":"This beef is tender and delicious.","grammar:8677:ex4:structure":"この＋noun＋は＋〔柔らかくて＋美味しい〕です. 「柔らかくて」 links with the te-form.","grammar:8677:ex4:words:0:zh":"this","grammar:8677:ex4:words:0:pos":"pre-noun adjectival","grammar:8677:ex4:words:1:zh":"beef","grammar:8677:ex4:words:1:note":"ぎゅうにく","grammar:8677:ex4:words:1:pos":"noun","grammar:8677:ex4:words:2:zh":"(topic marker)","grammar:8677:ex4:words:2:pos":"particle","grammar:8677:ex4:words:3:zh":"tender (and)","grammar:8677:ex4:words:3:note":"やわらかくて; i-adjective te-form","grammar:8677:ex4:words:3:pos":"adjective","grammar:8677:ex4:words:4:zh":"tasty","grammar:8677:ex4:words:4:note":"おいしい","grammar:8677:ex4:words:4:pos":"adjective","grammar:8677:ex4:words:5:zh":"(polite form)","grammar:8677:ex4:words:5:pos":"copula","grammar:8677:ex4:points:0":"i-adjective te-form: 柔らかい→柔らかくて (tender and …)","grammar:8677:ex4:points:1":"柔らかい: soft, tender","grammar:8677:ex5:trans":"Beef dishes are famous in Japan.","grammar:8677:ex5:structure":"〜では、牛肉料理が＋有名です. 「〜では」 means in/at … (as a setting).","grammar:8677:ex5:words:0:zh":"Japan","grammar:8677:ex5:words:0:note":"にほん","grammar:8677:ex5:words:0:pos":"noun","grammar:8677:ex5:words:1:zh":"(scene)","grammar:8677:ex5:words:1:pos":"particle","grammar:8677:ex5:words:2:zh":"beef dishes","grammar:8677:ex5:words:2:note":"ぎゅうにくりょうり","grammar:8677:ex5:words:2:pos":"noun","grammar:8677:ex5:words:3:zh":"(nominative)","grammar:8677:ex5:words:3:pos":"particle","grammar:8677:ex5:words:4:zh":"Famous","grammar:8677:ex5:words:4:note":"ゆうめい","grammar:8677:ex5:words:4:pos":"na-adjective","grammar:8677:ex5:words:5:zh":"(polite form)","grammar:8677:ex5:words:5:pos":"copula","grammar:8677:ex5:points:0":"〜では: in… (日本では = in Japan)","grammar:8677:ex5:points:1":"牛肉料理: beef dishes","exam:8677:zh":"Today I want beef rather than pork or chicken, so I'll buy beef.","exam:8677:why":"「牛肉」 is beef. 「豚肉」 is pork, which the sentence already rules out."},"8678":{"example:8678:exzh":"He is making light of the problem.","example:8678:exzh2":"Making light of things can lead to big mistakes.","example:8678:exzh3":"Don't brush it off, let's think about it more seriously.","example:8678:exzh4":"We shouldn't underestimate this impact.","example:8678:exzh5":"Dismissing it makes solving the problem harder."},"8679":{"example:8679:exzh":"My shoes are very comfortable.","example:8679:exzh2":"I want to buy new shoes.","example:8679:exzh3":"He put the shoes in the shoe cabinet.","example:8679:exzh4":"These shoes have a special design.","example:8679:exzh5":"My shoes got dirty, so I cleaned them.","grammar:8679:ex:trans":"My shoes are very comfortable.","grammar:8679:ex:structure":"〜はとても快適です","grammar:8679:ex:explain":"「快適だ」 is a na-adjective; at the end of a sentence it takes 「です」, and it becomes 「快適な」 only when modifying a noun, as in 「快適な靴」. 「とても」 goes before the adjective to strengthen the degree. The topic uses 「の」 to show possession: 「私の靴」 = my shoes. By the way, besides 「快適」, a more casual way to say shoes feel good is 「履き心地がいい」; the two can be swapped depending on the situation.","grammar:8679:ex:words:0:zh":"I","grammar:8679:ex:words:0:note":"わたし","grammar:8679:ex:words:0:pos":"pronoun","grammar:8679:ex:words:1:zh":"'s","grammar:8679:ex:words:1:pos":"particle","grammar:8679:ex:words:2:zh":"shoes","grammar:8679:ex:words:2:note":"くつ","grammar:8679:ex:words:2:pos":"noun","grammar:8679:ex:words:3:zh":"(topic)","grammar:8679:ex:words:3:pos":"particle","grammar:8679:ex:words:4:zh":"extremely","grammar:8679:ex:words:4:pos":"adverb","grammar:8679:ex:words:5:zh":"comfortable","grammar:8679:ex:words:5:note":"かいてき","grammar:8679:ex:words:5:pos":"na-adjective","grammar:8679:ex:words:6:zh":"(polite form)","grammar:8679:ex:words:6:pos":"copula","grammar:8679:ex:points:0":"❗靴 (くつ): shoes; 快適 = comfortable.","grammar:8679:ex:points:1":"快適な靴: comfortable shoes.","grammar:8679:ex2:trans":"I want to buy a new pair of shoes.","grammar:8679:ex2:structure":"〜を買いたいです","grammar:8679:ex2:words:0:zh":"new","grammar:8679:ex2:words:0:note":"あたらしい","grammar:8679:ex2:words:0:pos":"adjective","grammar:8679:ex2:words:1:zh":"shoes","grammar:8679:ex2:words:1:note":"くつ","grammar:8679:ex2:words:1:pos":"noun","grammar:8679:ex2:words:2:zh":"(object marker)","grammar:8679:ex2:words:2:pos":"particle","grammar:8679:ex2:words:3:zh":"want to buy","grammar:8679:ex2:words:3:note":"かいたい","grammar:8679:ex2:words:3:pos":"verb","grammar:8679:ex2:words:4:zh":"(polite form)","grammar:8679:ex2:words:4:pos":"copula","grammar:8679:ex2:points:0":"❗靴を買う: buy shoes; 〜たい = want to…","grammar:8679:ex2:points:1":"靴を買う: buy shoes.","grammar:8679:ex3:trans":"He put the shoes in the shoe cupboard.","grammar:8679:ex3:structure":"〜を〜にしまいました","grammar:8679:ex3:words:0:zh":"he","grammar:8679:ex3:words:0:note":"かれ","grammar:8679:ex3:words:0:pos":"pronoun","grammar:8679:ex3:words:1:zh":"(topic)","grammar:8679:ex3:words:1:pos":"particle","grammar:8679:ex3:words:2:zh":"shoes","grammar:8679:ex3:words:2:note":"くつ","grammar:8679:ex3:words:2:pos":"noun","grammar:8679:ex3:words:3:zh":"(object marker)","grammar:8679:ex3:words:3:pos":"particle","grammar:8679:ex3:words:4:zh":"shoe cupboard","grammar:8679:ex3:words:4:note":"くつばこ","grammar:8679:ex3:words:4:pos":"noun","grammar:8679:ex3:words:5:zh":"(the destination point)","grammar:8679:ex3:words:5:pos":"particle","grammar:8679:ex3:words:6:zh":"put away","grammar:8679:ex3:words:6:note":"しまいました","grammar:8679:ex3:words:6:pos":"verb","grammar:8679:ex3:points:0":"❗靴箱: shoe cupboard (靴 + 箱); 〜にしまう = to put away in…","grammar:8679:ex3:points:1":"靴箱にしまう: put away in the shoe cupboard.","grammar:8679:ex4:trans":"These shoes have a special design.","grammar:8679:ex4:structure":"〜は特別なデザインです","grammar:8679:ex4:words:0:zh":"these","grammar:8679:ex4:words:0:pos":"pronoun","grammar:8679:ex4:words:1:zh":"'s","grammar:8679:ex4:words:1:pos":"particle","grammar:8679:ex4:words:2:zh":"shoes","grammar:8679:ex4:words:2:note":"くつ","grammar:8679:ex4:words:2:pos":"noun","grammar:8679:ex4:words:3:zh":"(topic)","grammar:8679:ex4:words:3:pos":"particle","grammar:8679:ex4:words:4:zh":"special","grammar:8679:ex4:words:4:note":"とくべつ","grammar:8679:ex4:words:4:pos":"na-adjective","grammar:8679:ex4:words:5:zh":"(attributive form)","grammar:8679:ex4:words:5:pos":"auxiliary verb","grammar:8679:ex4:words:6:zh":"design","grammar:8679:ex4:words:6:note":"loanword","grammar:8679:ex4:words:6:pos":"noun","grammar:8679:ex4:words:7:zh":"is","grammar:8679:ex4:words:7:pos":"copula","grammar:8679:ex4:points:0":"❗特別なデザイン: a special design; これらの靴 = these shoes.","grammar:8679:ex4:points:1":"特別なデザイン: a special design.","grammar:8679:ex5:trans":"The shoes got dirty, so I cleaned them.","grammar:8679:ex5:structure":"〜が汚れたので掃除しました","grammar:8679:ex5:words:0:zh":"shoes","grammar:8679:ex5:words:0:note":"くつ","grammar:8679:ex5:words:0:pos":"noun","grammar:8679:ex5:words:1:zh":"(nominative)","grammar:8679:ex5:words:1:pos":"particle","grammar:8679:ex5:words:2:zh":"got dirty","grammar:8679:ex5:words:2:note":"よごれた","grammar:8679:ex5:words:2:pos":"verb","grammar:8679:ex5:words:3:zh":"because","grammar:8679:ex5:words:3:pos":"particle","grammar:8679:ex5:words:4:zh":"cleaned","grammar:8679:ex5:words:4:note":"そうじしました","grammar:8679:ex5:words:4:pos":"verb","grammar:8679:ex5:points:0":"❗靴が汚れる: the shoes get dirty (汚れる is an intransitive verb); 〜ので = because…","grammar:8679:ex5:points:1":"靴が汚れる: shoes get dirty.","exam:8679:zh":"Before going out, I put on my shoes in the entryway.","exam:8679:why":"The thing you wear on your feet is 「靴」. 「ズボン」 also goes with 「履く」, but pants are worn on your legs, so you can't say they go on your feet."},"8680":{"example:8680:exzh":"They sing in a choir.","example:8680:exzh2":"Teamwork is important in choir singing.","example:8680:exzh3":"There's a choir competition at school.","example:8680:exzh4":"She is practicing for choir.","example:8680:exzh5":"The choral piece is moving."},"8681":{"example:8681:exzh":"He started his own company.","example:8681:exzh2":"Starting a business comes with risks.","example:8681:exzh3":"She is attending a seminar on starting a business.","example:8681:exzh4":"Entrepreneurs are always thinking up new ideas.","example:8681:exzh5":"I want to start a business someday too."},"8682":{"example:8682:exzh":"He observed the stars with a telescope.","example:8682:exzh2":"With a telescope, you can see things far away.","example:8682:exzh3":"Scientists used a telescope to discover a new star.","example:8682:exzh4":"The kids are enjoying watching birds through a telescope.","example:8682:exzh5":"Please teach me how to use a telescope."},"8683":{"example:8683:exzh":"His beliefs are unchanging.","example:8683:exzh2":"This law is not something unchanging.","example:8683:exzh3":"They say human nature never changes.","example:8683:exzh4":"Love is an unchanging feeling.","example:8683:exzh5":"It's important to pursue unchanging truth."},"8684":{"example:8684:exzh":"His ashes were scattered in the sea.","example:8684:exzh2":"I decided to take the ashes back to my hometown.","example:8684:exzh3":"A ceremony was held to scatter the ashes.","example:8684:exzh4":"The urn for the ashes has a beautiful design.","example:8684:exzh5":"I pressed my hands together in prayer before the ashes."},"8685":{"example:8685:exzh":"We'll discuss the agenda at the next meeting.","example:8685:exzh2":"The agenda item is an important issue.","example:8685:exzh3":"Let's think about this agenda item.","example:8685:exzh4":"The submission of the agenda item was delayed.","example:8685:exzh5":"We need time to organize the agenda items."},"8686":{"example:8686:exzh":"The storage in this room is amazing.","example:8686:exzh2":"I want more storage space.","example:8686:exzh3":"Let's come up with better ways to store things.","example:8686:exzh4":"This piece of furniture is great for storage.","example:8686:exzh5":"I feel there isn't enough storage."},"8687":{"example:8687:exzh":"He is fighting for a noble cause.","example:8687:exzh2":"A noble cause has the power to move people.","example:8687:exzh3":"It's important to have a cause you believe in.","example:8687:exzh4":"His cause is respected.","example:8687:exzh5":"Let's unite for a common cause."},"8688":{"example:8688:exzh":"The children are playing innocently.","example:8688:exzh2":"I love her innocent smile.","example:8688:exzh3":"Innocent children become friends quickly.","example:8688:exzh4":"Sometimes I envy that innocence.","example:8688:exzh5":"He's innocent, but also a smart kid."},"8690":{"example:8690:exzh":"The iron has rusted.","example:8690:exzh2":"This broken bicycle is covered in rust.","example:8690:exzh3":"We painted it to prevent rust.","example:8690:exzh4":"When the rain keeps up, things rust easily.","example:8690:exzh5":"Rusty tools can't be used."},"8691":{"example:8691:exzh":"His opinion changed the situation.","example:8691:exzh2":"We have to do something about the situation.","example:8691:exzh3":"In this situation, staying calm is important.","example:8691:exzh4":"We were able to reach a new turn in the situation.","example:8691:exzh5":"The situation is getting tougher."},"8692":{"example:8692:exzh":"You must follow the current law.","example:8692:exzh2":"A problem occurred in the current program.","example:8692:exzh3":"We need to review the current system.","example:8692:exzh4":"This support is based on the current procedure.","example:8692:exzh5":"There are calls to change the current policy."},"8693":{"example:8693:exzh":"He is watching how the project turns out.","example:8693:exzh2":"Please tell me how it turned out.","example:8693:exzh3":"I hope it goes well.","example:8693:exzh4":"Did this turn out as planned?","example:8693:exzh5":"I'm satisfied with the outcome."},"8694":{"example:8694:exzh":"This house is made of cement.","example:8694:exzh2":"I need cement, so I'm going out to buy some."},"8695":{"example:8695:exzh":"He landed a smash in badminton.","example:8695:exzh2":"He's a player who's good at smashes."},"8696":{"example:8696:exzh":"He said things that stir up people's emotions.","example:8696:exzh2":"Stirring people up is a bad thing to do."},"8697":{"example:8697:exzh":"That newspaper published a scoop.","example:8697:exzh2":"I'm happy that I got the scoop."},"8698":{"example:8698:exzh":"Our company's policy is clear.","example:8698:exzh2":"A new policy has been introduced."},"8699":{"example:8699:exzh":"A certain company's product is getting a lot of attention.","example:8699:exzh2":"A certain person is involved in the incident."}};